import {TOOLS,index,optimizeOperations,launchSatellite} from './engine.mjs';
import {SEASONS,WEATHER,climate} from './climate.mjs';
import {OP_LABELS} from './utilities.mjs';
import {DESIGN_LABELS} from './environment.mjs';
import {ANALYTICS} from './render.mjs';
import {position,homeFor} from './geo.mjs';
import {dimensions} from './grid.mjs';
import {GRAPHICS_KEY} from './graphics.mjs';
const $=id=>document.getElementById(id),num=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
const row=(a,b)=>`<div class="budget-row"><span>${a}</span><b>${b}</b></div>`;
const options=(items,selected)=>items.map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('');
const ranges=(labels,values,prefix)=>Object.entries(labels).map(([k,v])=>`<label class="dial" for="${prefix}-${k}">${v}<output id="${prefix}-${k}-value">${values[k]}%</output></label><input id="${prefix}-${k}" type="range" min="0" max="100" step="5" value="${values[k]}">`).join('');
export function setupWorkbench(api){const {getCity,view,modal,refresh,changed,toast,setOverlay,pick,setTool,setView,getSelected,launches,download}=api;
 const nav=document.querySelector('nav');for(const [id,label]of [['environment-open','Weather & light'],['systems-open','City systems'],['models-open','Building models']]){const b=document.createElement('button');b.id=id;b.textContent=label;nav.prepend(b);}
 const analytic=document.createElement('select');analytic.id='analytics';analytic.setAttribute('aria-label','Analytics overlay');analytic.innerHTML=options(Object.entries(ANALYTICS),'city');document.querySelector('.layers').replaceChildren(analytic);analytic.onchange=()=>setOverlay(analytic.value);
 const group=document.createElement('div');group.className='map-controls-extra';group.innerHTML='<button id="underground">Underground</button><button id="orbit-view">Satellites</button><button id="focus-parcel">Focus</button><button id="region-view">Region</button><button id="rotate-left" aria-label="Rotate counterclockwise">↶</button><button id="rotate-right" aria-label="Rotate clockwise">↷</button>';document.querySelector('.map-shell').append(group);
 $('underground').onclick=()=>{view.underground=!view.underground;$('underground').classList.toggle('active',view.underground);view.orbital=false;setView({pitch:view.underground?55:50});changed();toast(view.underground?'Underground: choose a conduit and depth in City systems.':'Surface view.');};
 $('orbit-view').onclick=()=>{view.orbital=!view.orbital;view.underground=false;$('underground').classList.remove('active');$('orbit-view').classList.toggle('active',view.orbital);setView({zoom:view.orbital?13.3:14.75,pitch:55});changed();toast(`${getCity().satellites} satellites · orbital paths shown at a schematic scale.`);};
 $('focus-parcel').onclick=api.focus;$('region-view').onclick=()=>{view.cameraAltitude=0;view.followLaunch=false;setView(homeFor(getCity(),true));};for(const [id,sign]of [['rotate-left',-1],['rotate-right',1]])$(id).onclick=()=>api.rotate(sign*45);
 const construction=document.createElement('div');construction.className='build-settings';construction.innerHTML=`<label for="demolition">Bulldozer target</label><select id="demolition">${options([['surface','Surface building'],['pipe','Water pipe'],['wire','Power cable'],['tunnel','Metro tunnel'],['drain','Deep tunnel'],['elevated','Elevated rail']],'surface')}</select><label for="level-height">Level terrain to</label><input id="level-height" type="number" min="0" max="3000" step=".6" value="0" aria-label="Target terrain height in meters"><small>Meters above the map datum; maximum 3,000 m.</small><button id="bridge-design">Bridge design</button><button id="undo-build">Undo construction</button>`;$('build-options').append(construction);$('undo-build').onclick=api.undo;$('demolition').onchange=e=>{view.underground=e.target.value!=='surface';if(view.underground)view.network=e.target.value;$('underground').classList.toggle('active',view.underground);changed();};
 $('bridge-design').onclick=()=>{modal(`<h2>Shape a bridge</h2><p>Choose two clear, aligned land parcels across water or a valley. The span can be 3–24 parcels long.</p><label for="bridge-style">Structure</label><select id="bridge-style">${options([['cable','Sculptural cable stay'],['arch','Arch'] ],view.bridge.style)}</select><label class="dial" for="bridge-height">Rise <output id="bridge-h-value">${view.bridge.height} m</output></label><input id="bridge-height" type="range" min="15" max="90" value="${view.bridge.height}"><label class="dial" for="bridge-width">Deck width <output id="bridge-w-value">${view.bridge.width} m</output></label><input id="bridge-width" type="range" min="8" max="30" value="${view.bridge.width}"><button id="bridge-ready">Place endpoints</button>`);$('bridge-style').onchange=e=>view.bridge.style=e.target.value;for(const [id,key,out]of [['bridge-height','height','bridge-h-value'],['bridge-width','width','bridge-w-value']])$(id).oninput=e=>{view.bridge[key]=+e.target.value;$(out).textContent=e.target.value+' m';};$('bridge-ready').onclick=()=>{setTool('bridge');$('modal').close();};};
 const coordinates=document.createElement('section');coordinates.innerHTML='<div class="panel-label">GO TO PARCEL</div><div class="coordinate-inputs"><label>Column<input id="parcel-x" type="number" min="1" max="32" value="18"></label><label>Row<input id="parcel-y" type="number" min="1" max="32" value="18"></label></div><button id="parcel-action">Use selected tool here</button><button id="launch-satellite">Launch satellite · $12,000</button>';
 document.querySelector('.inspector').append(coordinates);$('parcel-action').onclick=()=>{const x=+$('parcel-x').value,y=+$('parcel-y').value;const c=getCity(),{width,height}=dimensions(c);if(!Number.isInteger(x)||!Number.isInteger(y)||x<1||x>width||y<1||y>height)return toast(`Choose a column 1–${width} and row 1–${height}.`);pick(index(x-1,y-1,c));};
 $('launch-satellite').onclick=()=>{const id=getSelected();if(launches.some(l=>l.pad===id&&performance.now()/1000-l.time<38))return toast('This pad is still launching.');const result=launchSatellite(getCity(),id);if(result.ok){launches.push({pad:id,time:performance.now()/1000});api.onLaunch?.(id);refresh();}toast(result.message);};
 $('environment-open').onclick=()=>{const c=getCity(),e=c.environment;modal(`<h2>Weather & light</h2><div class="control-grid"><label>Season<select id="season">${options(SEASONS.map(v=>[v,v==='auto'?'Seasonal calendar':v]),e.season)}</select></label><label>Weather<select id="weather">${options(WEATHER.map(v=>[v,v==='meteor'?'Falling stars':v]),e.weather)}</select></label></div><label class="dial" for="hour">Time of day <output id="hour-value"></output></label><input id="hour" type="range" min="0" max="23.75" step=".25" value="${e.lighting==='night'?22:e.hour??13}"><div class="range-labels"><span>Midnight</span><span>Noon</span><span>Midnight</span></div><label class="dial" for="wind">Wind <output id="wind-value">${e.wind} km/h</output></label><input id="wind" type="range" min="0" max="100" value="${e.wind}"><label class="policy"><input id="shadows" type="checkbox" ${view.shadows?'checked':''}>Cast sun shadows (experimental)</label><p class="modal-note">Firefox starts with cast shadows off for compatibility. This preference is saved. Sunlight, night windows, and street lights still work; enable shadows to test them on your GPU.</p><p id="climate-readout" class="readout"></p><p class="modal-note">Lighting and solar output respond to time and season. Powered streets illuminate at night. Weather also changes traffic, heat, and launch availability. Atmospheric fog and reflective water remain part of the realism roadmap.</p>`);
 const update=()=>{const state=climate(c),hour=+$('hour').value;$('hour-value').textContent=String(Math.floor(hour)).padStart(2,'0')+':'+String(Math.round(hour%1*60)).padStart(2,'0');$('climate-readout').textContent=`${state.night?'Night':'Daylight'} · ${state.season} · ${state.weather} · ${state.launchable?'Launch window open':'Weather hold'} · Solar elevation ${Math.round(Math.asin(state.sunHeight)*180/Math.PI)}°`;};
 for(const key of ['season','weather'])$(key).onchange=ev=>{e[key]=ev.target.value;refresh();update();};$('hour').oninput=ev=>{e.hour=+ev.target.value;e.lighting='day';refresh();update();};$('wind').oninput=ev=>{e.wind=+ev.target.value;$('wind-value').textContent=e.wind+' km/h';refresh();update();};$('shadows').onchange=ev=>{view.shadows=ev.target.checked;try{localStorage.setItem(GRAPHICS_KEY,JSON.stringify({shadows:view.shadows}));}catch{}changed();};update();};
 let baseline=null;
 $('systems-open').onclick=()=>{const c=getCity();modal(`<h2>City systems</h2><div class="workbench-tabs"><button data-tab="networks" class="active">Utilities</button><button data-tab="climate">Environment</button><button data-tab="data">Analytics</button></div><div id="system-panel"></div>`);const show=tab=>{document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='networks')networkPanel();else if(tab==='climate')environmentPanel();else dataPanel();$('modal').scrollTop=0;};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));show('networks');};
 function networkPanel(){const c=getCity();$('system-panel').innerHTML=`<div class="control-grid"><label>Underground network<select id="network">${options([['all','All systems'],['wire','Power · −3 m'],['pipe','Water · −6 m'],['tunnel','Metro · −18 m'],['drain','Deep tunnel · −35 m'],['elevated','Elevated rail · +18 m']],view.network)}</select></label><button id="show-cutaway">Open cutaway</button></div><label class="dial" for="cut-depth">Excavation depth <output id="cut-value">${view.cutDepth} m</output></label><input id="cut-depth" type="range" min="2" max="50" value="${view.cutDepth}"><div id="network-readout" class="readout"></div>${ranges(OP_LABELS,c.operations,'op')}<button id="optimize">Find lower-cost settings</button><div id="optimization" role="status"></div><p class="modal-note">Generation and water use simulation capacity units. Grid utilization is a citywide proxy, not a circuit-flow solution. The optimizer checks 12 thermal/pump combinations against current demand.</p>`;
 const metrics=()=>{const m=c.metrics,n=m.network;$('network-readout').innerHTML=row('Power demand / capacity',`${num(n.demand)} / ${num(m.powerCapacity)}`)+row('Water demand / capacity',`${num(n.waterDemand)} / ${num(m.waterCapacity)}`)+row('Grid / pipe losses',`${num(n.gridLoss)}% / ${num(n.waterLoss)}%`)+row('Reservoir stock',`${num(c.storage)} / ${num(n.stockCapacity)}`)+row('Disconnected cables / pipes',`${n.disconnectedCables} / ${n.disconnectedPipes}`)+row('Monthly operating expense','$'+num(m.expenses));};
 $('network').onchange=e=>{view.network=e.target.value;changed();};$('show-cutaway').onclick=()=>{view.underground=true;$('underground').classList.add('active');setView({pitch:55});changed();$('modal').close();};$('cut-depth').oninput=e=>{view.cutDepth=+e.target.value;$('cut-value').textContent=view.cutDepth+' m';changed();};
 for(const key of Object.keys(OP_LABELS))$('op-'+key).oninput=e=>{c.operations[key]=+e.target.value;$('op-'+key+'-value').textContent=e.target.value+'%';refresh();metrics();$('optimization').replaceChildren();};
 $('optimize').onclick=()=>{const result=optimizeOperations(c);if(!result.best||result.savings<=0){$('optimization').textContent='No cheaper combination meets at least 99% power and water coverage. Expand connections or capacity first.';return;}$('optimization').innerHTML=`<p>Candidate: save $${num(result.savings)}/month. Power ${result.best.power}% · Water ${result.best.water}%. Thermal ${result.best.operations.thermal}% · Pumps ${result.best.operations.water}%.</p><button id="apply-optimum">Apply candidate</button>`;$('apply-optimum').onclick=()=>{c.operations=result.best.operations;refresh();networkPanel();toast('Operating settings applied. Recheck after growth or weather changes.');};};metrics();}
 function environmentPanel(){const c=getCity();$('system-panel').innerHTML=`<p>Compare design changes against a snapshot of your city.</p><div id="environment-readout" class="readout"></div>${ranges(DESIGN_LABELS,c.design,'design')}<button id="capture-baseline">Capture comparison baseline</button><div id="comparison" class="readout"></div><p class="modal-note">Educational model with assumed coefficients. CO₂ accounting and local heat are separate. These values are not calibrated climate forecasts or engineering predictions. New construction records embodied carbon; changes do not erase historical emissions.</p>`;
 const metrics=()=>{const e=c.metrics.environment;$('environment-readout').innerHTML=row('Mean surface / local air',`${e.meanSurface}°C / ${e.meanAir}°C`)+row('Mean air above background',`${e.heatIsland}°C`)+row('Current-month CO₂ estimate',`${num(e.netCarbon)} t`)+row('Power / vehicles',`${num(e.electricity)} / ${num(e.cars)} t`)+row('Aircraft / industry',`${num(e.aircraft)} / ${num(e.industry)} t`)+row('Shipping / launches',`${num(e.shipping)} / ${num(e.launches)} t`)+row('Construction / tree removal',`${num(e.construction)} / −${num(e.removal)} t`)+row('Cumulative CO₂ ledger',`${num(e.cumulativeCarbon)} t`)+row('Runoff potential',`${e.runoffPercent}%`)+row('Monthly retrofit program','$'+num(e.retrofitCost));$('comparison').innerHTML=baseline?row('CO₂ change',`${num(e.netCarbon-baseline.netCarbon)} t/month`)+row('Surface temperature change',`${num(e.meanSurface-baseline.meanSurface)}°C`)+row('Expense change','$'+num(c.metrics.expenses-baseline.expenses)):'Capture a baseline to see differences.';};
 for(const key of Object.keys(DESIGN_LABELS))$('design-'+key).oninput=e=>{c.design[key]=+e.target.value;$('design-'+key+'-value').textContent=e.target.value+'%';refresh();metrics();};$('capture-baseline').onclick=()=>{baseline={...c.metrics.environment,expenses:c.metrics.expenses};metrics();};metrics();}
 function dataPanel(){const c=getCity();$('system-panel').innerHTML=`<p>View parcel attributes, relative heatmaps, and aggregated population in 3D.</p><label for="analysis-choice">Map layer</label><select id="analysis-choice">${options(Object.entries(ANALYTICS),$('analytics').value)}</select><div class="modal-actions"><button id="open-analysis">Show on map</button><button id="export-data">Export GeoJSON for kepler.gl</button><button id="export-kepler">Export kepler.gl map</button></div><div class="readout">${row('Property value','$'+num(c.metrics.propertyValue))}${row('Active metro / elevated stations',`${c.metrics.activeMetro} / ${c.metrics.activeElevated}`)}${row('Satellites',c.satellites)}${row('Parking spaces',c.metrics.parkingCapacity)}${row('Parking income / month','$'+num(c.metrics.parkingIncome))}</div><p class="modal-note">Population heatmap uses a relative density scale. Hexagons sum residents. Carbon allocation uses each parcel’s tax share; it is not a spatial emissions inventory. All simulation datasets are synthetic.</p>`;$('open-analysis').onclick=()=>{setOverlay($('analysis-choice').value);$('modal').close();};$('export-kepler').onclick=api.exportKepler;$('export-data').onclick=()=>{download('sim-city-2020-analytics.geojson',JSON.stringify({type:'FeatureCollection',features:c.tiles.map(t=>({type:'Feature',geometry:{type:'Point',coordinates:position(t.x+.5,t.y+.5,0,c)},properties:{parcel:t.id,zone:t.type,population:t.population,jobs:t.jobs,taxRevenue:t.taxRevenue,landValue:t.landPrice,buildingValue:t.buildingValue,traffic:t.traffic,surfaceTemp:t.surfaceTemp,airTemp:t.airTemp,allocatedCO2:t.carbon,power:t.powered,water:t.watered}}))},null,2));};}
 $('models-open').onclick=()=>{modal(`<h2>Detailed building models</h2><p>Assign a GLB model to a building category. PBR materials, embedded textures, and emissive materials are read from the asset.</p><div class="control-grid"><label>Building category<select id="model-type">${options(Object.entries(TOOLS).filter(([k])=>['residential','commercial','industrial','skyscraper','arcology','landmark','spaceport','port','power','airport','parking','garage'].includes(k)).map(([k,v])=>[k,v.name]),'skyscraper')}</select></label><label>Scale (meters per model unit)<input id="model-scale" type="number" min=".01" max="1000" step=".1" value="1"></label><label>Rotation (degrees)<input id="model-rotation" type="number" min="0" max="360" value="0"></label></div><label for="model-file" class="scene-label">Local GLB file</label><input id="model-file" type="file" accept=".glb"><p class="modal-note">Use a self-contained GLB with its origin at ground level. Imported models are session-only and must be reselected after reload. Clear models to return to the built-in geometry.</p><button id="clear-models">Clear imported models</button><p id="model-status" role="status"></p>`);$('model-file').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;const scale=+$('model-scale').value,rotation=+$('model-rotation').value;if(!Number.isFinite(scale)||scale<.01||scale>1000||!Number.isFinite(rotation)||rotation<0||rotation>360)return toast('Check model scale and rotation.');if(f.size>50e6)return toast('Use a GLB under 50 MB for this prototype.');const buffer=await f.slice(0,12).arrayBuffer();if(buffer.byteLength<12||new DataView(buffer).getUint32(0,true)!==0x46546c67)return toast('This file is not a binary glTF model.');const type=$('model-type').value;for(const m of view.models.filter(m=>m.type===type))URL.revokeObjectURL(m.url);view.models=view.models.filter(m=>m.type!==type);view.models.push({type,url:URL.createObjectURL(f),scale,rotation});changed();$('model-status').textContent=f.name+' assigned. Close this panel to view it.';};$('clear-models').onclick=()=>{for(const m of view.models)URL.revokeObjectURL(m.url);view.models=[];changed();$('model-status').textContent='Built-in models restored.';};};
}
